UPDATE companies SET description='Averra Packaging operates from West Valley City, Utah. The company traces its roots to 1989, when it began thermoforming out of a garage. Today it runs a 40,000-square-foot sterile healthcare packaging design and manufacturing facility.

The company designs and manufactures custom medical packaging — including trays, lids, and fulfillment services — as well as consumer packaging. Its process covers design and development, in-house prototyping that delivers true thermoformed samples in days, a Bridge Tooling™ step for production-equivalent parts, in-house tooling via its own machine shop, and full-scale production. The facility is ISO 13485:2016 and ISO 9001:2015 certified, operates a Class 8 cleanroom, and uses redundant equipment to handle volumes from hundreds to tens of millions of parts.

Averra serves the medical device and consumer goods industries. Its medical customers include companies developing life-altering devices that require sterile barrier systems, while its consumer division focuses on high-quality retail packaging. The firm also acts as a manufacturer of record, combining packaging expertise with regulatory documentation under one roof.

The company says it was driven by a purpose to deliver smart, effective packaging that meets modern business demands, emphasizing that the only barrier between a device and patient outcomes should be a sterile one. It highlights sustainable practices: 75 percent of materials contain recycled content, one million pounds of post-production waste are recycled annually, and 96 percent of its products are recyclable.', certifications=ARRAY['ISO 13485:2016','ISO 9001:2015']::text[], profile='{"capabilities": ["Design & Development", "Prototyping", "Bridge Tooling", "Tooling", "Production", "Fulfillment", "Cleanroom manufacturing (Class 8)", "In-house machine shop", "Thermoforming", "Custom medical packaging", "Consumer packaging", "Manufacturer-of-record services", "Sustainable packaging solutions"], "industries": ["Medical device", "Consumer goods", "Healthcare"], "materials": [], "equipment": [], "volume": "Hundreds to tens of millions of parts", "lead_time": "Prototypes in days; production tooling 30-60 business days", "tolerances": "", "built_on": ["In-house prototyping delivering true thermoformed samples in days", "Bridge Tooling\u2122 process for production-equivalent parts before full production", "In-house machine shop producing tooling to exacting tolerances", "ISO 13485:2016 and ISO 9001:2015 certified with Class 8 cleanroom manufacturing", "Redundant equipment and stocking programs ensuring on-time delivery"], "facts_used": ["Founded 1989, garage start -> /about", "40,000 sq-ft sterile healthcare packaging facility -> /about", "ISO 13485:2016 and ISO 9001:2015 certified -> /capabilities", "Class 8 cleanroom manufacturing -> /capabilities", "In-house prototyping in days -> /capabilities", "Bridge Tooling\u2122 for production-equivalent parts -> /capabilities", "In-house machine shop for tooling -> /capabilities", "Redundant equipment and stocking programs -> /capabilities", "Volumes from hundreds to tens of millions -> /about", "75% materials from recycled content -> /about", "1,000,000 lbs post-production waste recycled annually -> /about", "96% products recyclable -> /about", "Serves medical device and consumer goods industries -> /", "Manufacturer-of-record capabilities -> /capabilities", "CEO Tim Nieman, leadership team listed -> /about", "Headquarters West Valley City, Utah -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "From our humble beginnings thermoforming out of a garage in 1989, we''ve evolved into a 40,000 sq-ft sterile healthcare packaging design & manufacturing facility.", "founded_year": "1989", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='averra-packaging' AND approved AND profile IS NULL;
UPDATE companies SET description='Azuma Foods International Inc. USA (AFI) was founded in 1990 and is headquartered in East Rutherford, New Jersey.

The company maintains an in-house laboratory equipped with PCR thermal cyclers and ELISA testing systems for microbiological and chemical analysis, and operates under a HACCP-based quality management system that covers hazard analysis, sanitation standard operating procedures, allergen control, gluten testing, and a Foreign Supplier Verification Program. All foreign suppliers must provide HACCP plans and certificates of compliance aligned with FDA guidelines.

The company serves the food service industry, supplying distributors, restaurants, and retail accounts such as Costco, which audits AFI under its GMP program. AFI’s Sea Salad brand, featuring award-winning calamari salad and seaweed salad, has been recognized as a 2020 Seafood Excellence Awards finalist for its Island Style Marinated Ogo Seaweed.

AFI’s founding mission is to achieve an “Assimilation of Food Culture to the World” by blending traditional Japanese cuisine with global food traditions. The company emphasizes sustainable, vegetarian-friendly products with no added colors, and differentiates itself through its in-house laboratory capabilities, stringent supplier verification, and ongoing pursuit of SQF certification.', certifications=ARRAY['HACCP','SQF']::text[], profile='{"capabilities": ["Seafood importation and distribution", "HACCP-based food safety management", "In-house microbiological and chemical laboratory testing (PCR, ELISA, culture methods)", "New product development", "Allergen and gluten control programs", "Foreign Supplier Verification Program (FSVP) compliance", "Kosher certification coordination", "Good Manufacturing Practices (GMP) implementation", "Sanitation standard operating procedures (SSOP) management", "Quality assurance and quality control monitoring"], "industries": ["Food Service"], "materials": ["Flying fish roe (Tobikko)", "Capelin roe (Masago)", "Ogo seaweed", "Calamari", "Tofu", "Shrimp", "Sesame"], "equipment": ["PCR thermal cyclers", "ELISA testing systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["\"Assimilation of Food Culture to the World\" mission blending Japanese and global cuisines", "In-house laboratory with PCR thermal cyclers and ELISA testing for pathogen detection", "HACCP-certified quality system with mandatory foreign supplier HACCP plan submission", "2020 Seafood Excellence Awards finalist for Island Style Marinated Ogo Seaweed", "Sustainable, vegetarian-friendly product lines with no added colors"], "facts_used": ["Founded 1990 -> db", "Headquarters East Rutherford, New Jersey -> db", "HACCP and SQF certifications -> db", "Products: Tobikko, Masago, Dry Toppings, Seaweed Salad, Calamari Salad, New Product Development -> db", "Industry: Food Service -> db", "In-house laboratory with PCR thermal cyclers and ELISA testing -> /qua